define(["jquery", "Magento_Ui/js/modal/modal", "Magento_Customer/js/customer-data", "mage/storage", "mage/translate", "mage/mage", "jquery/validate", ], function($, modal, customerData, storage, $t) {
    "use strict";
    $.widget("eighteentech.customerAuthenticationPopup", {
        options: {
            login: "#eighteentech-login-popup",
            nextRegister: "#customer-popup-registration",
            register: "#customer-popup-register",
            prevLogin: "#customer-popup-sign-in",
            class_login: [],
            class_register: [],
            isPopup: '',
            formLoginUrl: '',
            forgotFormUrl: '',
            createFormUrl: '',
            recaptchaLogin: '',
            recaptchaForgot: '',
            recaptchaCreate: '',
            recaptchaSitekey: '',
            recaptchaTheme: '',
            recaptchaType: '',
            recaptchaSize: '',
            popuphtml: ''
        },
        _create: function() {
            var $widget = this;
            $widget._EventListener();
        },
        _init: function() {
            this.options.popuphtml = $("#login_overlay").html();
        },
        _EventListener: function() {
            var $widget = this;
            $(document).keypress(function(event) {
                if (event.which == '13') {
                    event.preventDefault();
                }
            });
            $(document).on('click', '#change-number-id , #change-number', function() {
                $("#customer-popup-form-register").hide();
                $('#login_overlay').find('.login-register-popup').find('#login-container').css('display', 'block');
                $(".tab-recaptcha").show();
                $(".tab-recaptcha").removeClass('d-none');
                $('#customer-popup-login-form11 .recaptcha.field.required').show();
                $("#double_send_otp_login").addClass('dsabled-active');
                grecaptcha.reset();
            });
            $(document).on("click", '#customer-popup-registration', function(e) {
                e.preventDefault();
                $("#customer-popup-form-register").show();
                $('#customer-popup-form-register').find('#res_form').show();
                $('#customer-popup-form-register').find('#otp-verifaction-fields').hide();
                $('#customer-popup-form-register').find('#reg-create-acc').show();
                $('#customer-popup-form-register').find('#reg-verif_otp').hide();
                var loginTitle = $('.login-register-popup').find('#popup-title').html();
                if (loginTitle) {
                    $('.register-container').find('#popup-title').html(loginTitle);
                    $(".smserror").hide();
                }
                $(".tab-recaptcha").show();
                $('label.label').css('display', 'block');
                $widget._OnClick($(this));
            });
            $(document).keypress(function(event) {
                if (event.which == '13') {
                    if ($("#res_digit-1").val() != "" && $("#res_digit-1").val() != "" && $("#res_digit-1").val() != "" && $("#res_digit-1").val() != "") {
                        $("#reg-verif_otp").trigger("click");
                    }
                    event.preventDefault();
                }
            });
            $("#reg-create-acc").click(function(e) {
                e.preventDefault();
                $("#cap-valid").remove();
                var emailAddress = $("#email_address").val();
                if (emailAddress && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailAddress)) {
                    $("#cap-valid").remove();
                    $("#reg-create-acc").before("<p id='cap-valid' style='color:red;'>Please enter a valid email address</p>");
                    return false;
                }
                if ($("#customer-popup-form-register #g-recaptcha-response-1").val() == '') {
                    $("#cap-valid").remove();
                    $("#reg-create-acc").before("<p id='cap-valid' style='color:red;'>Captcha is required</p>");
                    return false;
                }
                $widget._AjaxSendOtp();
            });
            $("#reg-verif_otp").click(function() {
                $widget._AjaxOtpVerify();
            });
            $(document).ready(function() {
                $('.otp-field').on('input', function() {
                    if ($(this).val().length === 1) {
                        $(this).next('.otp-field').focus();
                    }
                });
                $('.otp-field').on('keydown', function(e) {
                    if (e.key === "Backspace" && $(this).val() === "") {
                        $(this).prev('.otp-field').focus();
                    }
                });
            });
        },
        _OnClick: function($this) {
            $.fancybox({
                openEffect: 'none',
                closeEffect: 'none',
                prevEffect: 'none',
                nextEffect: 'none',
                width: "auto",
                height: 'auto',
                fitToView: false,
                autoSize: false,
                maxWidth: '98%',
                content: "",
            });
            $('#login-recaptcha,#fogot-recaptcha,#create-recaptcha').val('');
            var element_render = '';
            var validate = '';
            element_render = 'tab-create-recaptcha';
            validate = 'create-recaptcha';
            if ($('#' + element_render).children().length === 0 && this.options.recaptchaSitekey != "") {
                grecaptcha.render(element_render, {
                    'sitekey': this.options.recaptchaSitekey,
                    'theme': "light",
                    'type': "image",
                    'size': "normal",
                    'callback': function(response) {
                        if (response.length > 0) {
                            $('#' + validate).val('success');
                            $('#reg-create-acc').prop('disabled', false);
                            $('#cap-valid').remove();
                            $('#reg-create-acc').removeClass('disabled-active');
                        }
                    }
                });
            }
        },
        _AjaxSendOtp: function() {
            var isValid = false;
            if ($("#customer-popup-form-register #firstname").val() == '') {
                $("#firstname-error").remove();
                $("#customer-popup-form-register #firstname").after('<div for="firstname" generated="true" class="mage-error" id="firstname-error">Enter first and last name.</div>');
                isValid = true;
            }
            if (isValid) {
                return false;
            }
            var self = this;
            var captcha_res = $(".login_popup_form #g-recaptcha-response").val();
            var mobile = $('.login-register-popup').find('#mobile_login').val();
            if (!mobile) {
                alert("Please enter mobile number");
                return false;
            }
            var sendotpurl = $(".sendUrl").val();
            $.ajax({
                showLoader: true,
                url: location.origin + "/" + sendotpurl,
                method: "POST",
                data: {
                    mobile: mobile,
                    eventType: "customer_signup_otp",
                    resend: 0,
                    captcha: captcha_res
                },
                dataType: "json"
            }).done(function(response) {
                const decodedData = atob(atob(response.Success).split("").reverse().join(""));
                if (decodedData === "success-" + mobile) {
                    $("#cap-valid").remove();
                    $("#otp-verifaction-fields #fname").html($("#firstname").val());
                    $("#otp-verifaction-fields #registration_mobile").val(mobile);
                    $("#res_form").hide();
                    $("#otp-verifaction-fields .title-name").html("");
                    $("#otp-verifaction-fields .title-name").html("Verify with OTP sent to +91" + mobile + " <span id='change-number-id'>Change</span>");
                    $("#reg-create-acc").hide();
                    $("#button-text").hide();
                    $("#otp-verifaction-fields").attr("style", "display:block !important;");
                    $("#reg-verif_otp").show();
                    $("#resend-otp-timer-reg").show();
                    $(".tab-recaptcha").hide();
                    $(".tab-recaptcha").addClass('d-none');
                    self._loadTimer(120);
                } else {
                    if (decodedData != 'success-' + mobile) {
                        $(".otp_generatenote").html('<p class="captcha_err" style="color:red;">Something want wrong, please refersh the page.</p>');
                    } else {
                        $(".otp_generatenote").html('<p class="captcha_err" style="color:red;">' + decodedData + '</p>');
                    }
                }
            });
            return false;
        },
        _AjaxOtpVerify: function() {
            var sendotpurlLogin = $(".verifyUrlLogin").val();
            var otp = $("#res_digit-1").val() +
                $("#res_digit-2").val() +
                $("#res_digit-3").val() +
                $("#res_digit-4").val();
            if (otp.length == 4) {
                var mobile = $('.login-register-popup').find('#mobile_login').val();
                var sendotpurl = location.origin + "/smsprofile/otp/verify/";
                $.ajax({
                    showLoader: true,
                    url: sendotpurl,
                    method: "POST",
                    data: {
                        otp: otp,
                        mobile: mobile,
                    },
                    dataType: "json",
                }).done(function(response) {
                    const jsonData = JSON.parse(atob(atob(response.message)));
                    const finalMsg = atob(atob(jsonData.status).split("").reverse().join(""));
                    if (finalMsg === 'Verified-' + otp) {
                        if (response) {
                            $(document).find(".otp_generatenote").html("");
                            $(document).find(".otp_generatenote").fadeIn();
                            $(".otp_text").html(response.message);
                            const sendloginuser = location.origin + "/customerlogin/ajax/register";
                            $.ajax({
                                showLoader: true,
                                url: sendloginuser,
                                method: "POST",
                                data: {
                                    phone: mobile,
                                    fname: $('#customer-popup-form-register #firstname').val(),
                                    lname: $('#customer-popup-form-register #lastname').val(),
                                    email: $('#customer-popup-form-register #email_address').val(),
                                },
                                dataType: "json",
                                success: function(response) {
                                    jQuery("#otp-verifaction .confirm-title .title").html("<p class='success'>OTP Verified Successfully!</p>");
                                    jQuery("#confirmation_screen #customer_fname").html($('#customer-popup-form-register #firstname').val());
                                    jQuery("#hide-id").show();
                                    if (response.success == false) {
                                        let token = atob(response.msg);
                                        let payloadJson = atob(token);
                                        let payload = JSON.parse(payloadJson);
                                        let statusMsg = atob(payload.status);
                                        statusMsg = statusMsg.split("").reverse().join("");
                                        statusMsg = atob(statusMsg);
                                        jQuery("#msg-icon").html(statusMsg);
                                        jQuery("#hide-id").hide();
                                    }
                                    var sections = ['cart', 'customer', 'emailPopup'];
                                    customerData.invalidate(sections);
                                    customerData.reload(sections, true);
                                    var cartData = customerData.get('cart');
                                    var count = cartData().summary_count || 0;
                                    var now = new Date();
                                    now.setTime(now.getTime() + (10 * 1000));
                                    if (count > 0) {
                                        $.cookie('isRegisterGT', '1', {
                                            path: '/',
                                            expires: now
                                        });
                                        location.href = window.checkout.shoppingCartUrl;
                                    } else {
                                        $.cookie('isRegisterGT', '1', {
                                            path: '/',
                                            expires: now
                                        });
                                        location.reload();
                                    }
                                },
                                error: function(xhr, status, errorThrown) {
                                    console.log('Error happens. Try again.');
                                    console.log(errorThrown);
                                }
                            });
                        }
                    } else {
                        $('.smserror, .success_msg_mobile, .captcha_err').show();
                        $("#otp-verifaction-fields .title-name").after('<div class="smserror"><p class="success" style="color:red;">Incorrect OTP. Please try again</p></div>');
                    }
                });
            } else {
                alert("Please enter OTP");
            }
            return false;
        },
        _setStyleCss: function(width) {
            width = width || 400;
            if (window.innerWidth > 786) {
                this.element.parent().parent(".modal-inner-wrap").css({
                    "max-width": width + "px"
                });
            }
        },
        _resetStyleCss: function() {
            var self = this;
            $(window).resize(function() {
                if (window.innerWidth <= 786) {
                    self.element.parent().parent(".modal-inner-wrap").css({
                        "max-width": "initial"
                    });
                } else {
                    self._setStyleCss(self.options.innerWidth);
                }
            });
        },
        _ajaxSubmit: function() {
            var self = this,
                form = this.element.find("form"),
                inputElement = form.find("input");
            inputElement.keyup(function(e) {
                self.element.find(".messages").html("");
            });
            form.submit(function(e) {
                if (form.validation("isValid")) {
                    if (form.hasClass("form-create-account")) {
                        $.ajax({
                            url: $(e.target).attr("action"),
                            data: $(e.target).serializeArray(),
                            showLoader: true,
                            type: "POST",
                            dataType: "json",
                            success: function(response) {
                                self._showResponse(response, form.find('input[name="redirect_url"]').val());
                            },
                            error: function() {
                                self._showFailingMessage();
                            },
                        });
                    } else {
                        var submitData = {},
                            formDataArray = $(e.target).serializeArray();
                        formDataArray.forEach(function(entry) {
                            submitData[entry.name] = entry.value;
                        });
                        $("body").loader().loader("show");
                        storage.post($(e.target).attr("action"), JSON.stringify(submitData)).done(function(response) {
                            $("body").loader().loader("hide");
                            self._showResponse(response, form.find('input[name="redirect_url"]').val());
                        }).fail(function() {
                            $("body").loader().loader("hide");
                            self._showFailingMessage();
                        });
                    }
                }
                return false;
            });
        },
        _displayMessages: function(className, message) {
            $('<div class="message ' +
                className + '"><div>' +
                message + "</div></div>").appendTo(this.element.find(".messages"));
        },
        _showResponse: function(response, locationHref) {
            var self = this,
                timeout = 800;
            this.element.find(".messages").html("");
            if (response.errors) {
                this._displayMessages("message-error error", response.message);
            } else {
                this._displayMessages("message-success success", response.message);
            }
            this.element.find(".messages .message").show();
            setTimeout(function() {
                if (!response.errors) {
                    self.element.modal("closeModal");
                    window.location.href = locationHref;
                }
            }, timeout);
        },
        _showFailingMessage: function() {
            this.element.find(".messages").html("");
            this._displayMessages("message-error error", $t("An error occurred, please try again later."));
            this.element.find(".messages .message").show();
        },
        _loadTimer: function(sec) {
            var self = this;
            var timer;
            $('.main-timer-reg').css('display', 'inline-block');
            $('#otp-resend-reg').prop('disabled', true).text('Resend in').css({
                'color': '#b9b9b9',
                'text-decoration': 'none'
            });
            if (self._resendTimer) clearInterval(self._resendTimer);
            self._resendTimer = setInterval(function() {
                var m = Math.floor(sec / 60);
                var s = sec % 60;
                m = m < 10 ? '0' + m : m;
                s = s < 10 ? '0' + s : s;
                $('#timer-reg').text(m + ':' + s);
                sec -= 1;
                if (sec < 0) {
                    clearInterval(self._resendTimer);
                    $('#otp-resend-reg').prop('disabled', false).css('color', '#cb2227').text('Resend OTP');
                    $('.main-timer-reg').hide();
                    $("#otp-resend-reg").off('click').on('click', function(e) {
                        e.preventDefault();
                        var captcha_res = $("#create-recaptcha").val();
                        var mobile = $('.login-register-popup').find('#mobile_login').val();
                        if (!mobile) {
                            alert("Please enter mobile number");
                            return false;
                        }
                        var sendotpurl = $(".sendUrl").val();
                        $.ajax({
                            url: location.origin + "/" + sendotpurl,
                            method: "POST",
                            data: {
                                mobile: mobile,
                                eventType: "customer_signup_otp",
                                resend: 1,
                                isResend: 1,
                                captcha: captcha_res
                            },
                            dataType: "json"
                        }).done(function(response) {
                            const decodedData = atob(atob(response.Success).split("").reverse().join(""));
                            if (decodedData === "success-" + mobile) {
                                $("#otp-verifaction-fields #fname").html($("#firstname").val());
                                $("#otp-verifaction-fields #registration_mobile").val(mobile);
                                $("#res_form, .recaptcha, #reg-create-acc, #button-text").hide();
                                $("#otp-verifaction-fields").show();
                                $("#reg-verif_otp, #resend-otp-timer-reg").show();
                                self._loadTimer(120);
                            } else {
                                if (decodedData != 'success-' + mobile) {
                                    $(".otp_generatenote").html('<p class="captcha_err" style="color:red;">Something want wrong, please refersh the page.</p>');
                                } else {
                                    $(".otp_generatenote").html('<p class="captcha_err" style="color:red;">' + decodedData + '</p>');
                                }
                            }
                        });
                    });
                }
            }, 1000);
        }
    });
    return $.eighteentech.customerAuthenticationPopup;
});